import { LitElement, html, css } from 'lit';
import { EVENT_KEYDOWN } from './constants.js';
import { showToast } from './utils.js';

const ERROR_TYPES = {
    PERMISSION: { patterns: ['permission', '403'], message: 'You do not have permission to copy this fragment' },
    NOT_FOUND: { patterns: ['not found', '404'], message: 'Fragment not found. It may have been deleted.' },
    NETWORK: { patterns: ['network', 'Network'], message: 'Network error. Please check your connection and try again.' },
};

export class MasCopyDialog extends LitElement {
    static properties = {
        fragment: { type: Object },
        selectedFolder: { state: true },
        selectedLocale: { state: true },
        loading: { state: true },
        error: { state: true },
    };

    static styles = css`
        :host {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: 999;
            display: block;
        }

        .dialog-backdrop {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(4px);
            z-index: 999;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }

        sp-dialog-wrapper {
            z-index: 1000;
            position: relative;
            max-height: 90vh;
            display: flex;
            flex-direction: column;
            background: var(--spectrum-white);
            border-radius: 16px;
            --spectrum-dialog-max-height: 90vh;
            --spectrum-dialog-content-overflow-y: auto;
        }

        .form-field {
            margin-bottom: var(calc(var(--swc-scale-factor) * 32px));
        }

        sp-field-label {
            display: block;
            margin-bottom: var(calc(var(--swc-scale-factor) * 8px));
        }

        .folder-tree {
            max-height: 200px;
            overflow-y: auto;
            border: 1px solid var(--spectrum-gray-300);
            border-radius: 4px;
            padding: 8px;
        }

        .folder-item {
            padding: 4px 8px;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .folder-item:hover {
            background-color: var(--spectrum-gray-200);
        }

        .folder-item.selected {
            background-color: var(--spectrum-blue-400);
            color: white;
        }

        .folder-item.disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .folder-icon {
            width: 16px;
            height: 16px;
        }

        .current-path {
            font-size: 12px;
            color: var(--spectrum-gray-700);
            margin-bottom: 8px;
        }

        .error-message {
            color: var(--spectrum-red-600);
            font-size: 12px;
            margin-top: 8px;
        }

        sp-textfield {
            width: 100%;
        }

        sp-picker {
            width: 100%;
        }
    `;

    constructor() {
        super();
        this.fragment = null;
        this.selectedFolder = null;
        this.selectedLocale = 'en_US';
        this.loading = false;
        this.error = null;
        this.merchFolders = [];
        this.aem = null;

        this.handleSubmit = this.handleSubmit.bind(this);
        this.close = this.close.bind(this);
        this.handleKeyDown = this.handleKeyDown.bind(this);
    }

    connectedCallback() {
        super.connectedCallback();
        document.addEventListener(EVENT_KEYDOWN, this.handleKeyDown);
        this.aem = document.querySelector('mas-repository')?.aem;

        if (this.aem) {
            this.loadMerchFolders();
        } else {
            this.error = 'AEM instance not available';
            this.loading = false;
        }
    }

    updated(changedProperties) {
        super.updated(changedProperties);

        if (this.aem && this.merchFolders.length === 0 && !this.loading) {
            this.loadMerchFolders();
        }
    }

    disconnectedCallback() {
        super.disconnectedCallback();
        document.removeEventListener(EVENT_KEYDOWN, this.handleKeyDown);
    }

    handleKeyDown(event) {
        if (event.key === 'Escape' && this.dialog?.open) {
            this.close();
        }
    }

    get dialog() {
        return this.shadowRoot.querySelector('sp-dialog-wrapper');
    }

    updated() {
        this.open();
    }

    async open() {
        await this.updateComplete;
        this.dialog.open = true;
    }

    async loadMerchFolders() {
        try {
            this.loading = true;

            const aem = this.aem;
            if (!aem) {
                throw new Error('AEM instance not available');
            }

            const rootPath = '/content/dam/mas';
            const result = await aem.folders.list(rootPath);

            const allowedFolders = ['nala', 'sandbox'];

            this.merchFolders = result.children
                .filter((folder) => allowedFolders.includes(folder.name.toLowerCase()))
                .map((folder) => ({
                    ...folder,
                    displayName: folder.name.replace(/-/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase()),
                    fullPath: folder.path,
                }));

            this.loading = false;
        } catch (err) {
            this.error = 'Failed to load folders';
            this.loading = false;
            console.error('Error loading folders:', err);
        }
    }

    selectFolder(folder) {
        this.selectedFolder = folder;
        this.error = null;
    }

    validateInputs() {
        if (!this.selectedFolder) {
            this.error = 'Please select a destination folder';
            return false;
        }

        if (!this.aem) {
            this.error = 'AEM instance not available';
            return false;
        }

        if (!this.fragment?.path) {
            this.error = 'Fragment is missing path property';
            return false;
        }

        return true;
    }

    showSuccessMessage(copiedFragment) {
        const folderName = this.selectedFolder.displayName;
        const localeName = this.selectedLocale;
        showToast(`Fragment copied to ${folderName} (${localeName})`, 'positive');
    }

    handleCopyError(error) {
        this.error = error.message || 'Failed to copy fragment';
        this.loading = false;

        const errorMessage = error.message || '';

        for (const [, config] of Object.entries(ERROR_TYPES)) {
            if (config.patterns.some((pattern) => errorMessage.includes(pattern))) {
                showToast(config.message, 'negative');
                return;
            }
        }

        showToast(`Failed to copy fragment: ${error.message}`, 'negative');
    }

    extractSubfolderPath() {
        if (!this.fragment?.path || !this.selectedFolder?.fullPath) {
            return '';
        }

        const fragmentPath = this.fragment.path;
        const surfacePath = this.selectedFolder.fullPath;

        const pathParts = fragmentPath.split('/');
        const surfaceParts = surfacePath.split('/');

        const surfaceIndex = pathParts.findIndex(
            (part, idx) => idx < pathParts.length - 2 && part === surfaceParts[surfaceParts.length - 1],
        );

        if (surfaceIndex === -1) return '';

        const localeIndex = pathParts.findIndex((part, idx) => idx > surfaceIndex && /^[a-z]{2}_[A-Z]{2}$/.test(part));

        if (localeIndex === -1 || localeIndex <= surfaceIndex + 1) return '';

        return pathParts.slice(surfaceIndex + 1, localeIndex).join('/');
    }

    async performCopy() {
        const subfolderPath = this.extractSubfolderPath();
        const targetPath = subfolderPath ? `${this.selectedFolder.fullPath}/${subfolderPath}` : this.selectedFolder.fullPath;

        const copiedFragment = await this.aem.sites.cf.fragments.copyToFolder(
            this.fragment,
            targetPath,
            null,
            this.selectedLocale,
        );

        if (!copiedFragment) {
            throw new Error('Copy operation completed but could not retrieve copied fragment');
        }

        return copiedFragment;
    }

    async handleSubmit() {
        if (!this.validateInputs()) return;

        try {
            this.loading = true;
            showToast(`Copying fragment to ${this.selectedFolder.displayName}...`);

            const copiedFragment = await this.performCopy();
            this.showSuccessMessage(copiedFragment);

            this.dispatchEvent(
                new CustomEvent('fragment-copied', {
                    detail: { fragment: copiedFragment },
                    bubbles: true,
                    composed: true,
                }),
            );
        } catch (err) {
            this.handleCopyError(err);
        }
    }

    close() {
        this.dialog.open = false;
        this.dispatchEvent(
            new CustomEvent('cancel', {
                bubbles: true,
                composed: true,
            }),
        );
    }

    render() {
        return html`
            <div class="dialog-backdrop" @click=${this.handleBackdropClick}>
                <sp-dialog-wrapper
                    headline="Copy fragment"
                    mode="modal"
                    confirm-label="Copy"
                    cancel-label="Cancel"
                    @confirm=${this.handleSubmit}
                    @cancel=${this.close}
                    ?dismissable=${!this.loading}
                    @click=${(e) => e.stopPropagation()}
                >
                    <div class="form-field">
                        <sp-field-label for="locale-picker">Select Locale</sp-field-label>
                        <mas-locale-picker
                            id="locale-picker"
                            locale=${this.selectedLocale}
                            @locale-changed=${(e) => (this.selectedLocale = e.detail.locale)}
                        ></mas-locale-picker>
                    </div>

                    <div class="form-field">
                        <sp-field-label for="folder-picker">Select Destination Folder</sp-field-label>

                        ${this.loading
                            ? html` <sp-progress-circle indeterminate></sp-progress-circle> `
                            : html`
                                  <div class="folder-tree">
                                      ${this.merchFolders.length === 0
                                          ? html`<div class="error-message">No folders available</div>`
                                          : this.merchFolders.map((folder) => {
                                                return html`
                                                    <div
                                                        class="folder-item ${this.selectedFolder?.fullPath === folder.fullPath
                                                            ? 'selected'
                                                            : ''}"
                                                        @click=${() => this.selectFolder(folder)}
                                                        title="${folder.fullPath}"
                                                    >
                                                        <sp-icon-folder size="m" class="folder-icon"></sp-icon-folder>
                                                        <span>${folder.displayName}</span>
                                                    </div>
                                                `;
                                            })}
                                  </div>
                              `}
                        ${this.error ? html` <div class="error-message">${this.error}</div> ` : ''}
                    </div>
                </sp-dialog-wrapper>
            </div>
        `;
    }

    handleBackdropClick(event) {
        if (event.target.classList.contains('dialog-backdrop') && !this.loading) {
            this.close();
        }
    }
}

customElements.define('mas-copy-dialog', MasCopyDialog);

import { PATH_TOKENS, PZN_FOLDER, TAG_PROMOTION_PREFIX } from '../constants.js';

export class Fragment {
    path = '';
    hasChanges = false;
    status = '';

    fields = [];

    selected = false;

    initialValue;

    /**
     * @param {*} AEM Fragment JSON object
     */
    constructor(fragment) {
        this.refreshFrom(fragment);
    }

    getField(fieldName) {
        return this.fields.find((field) => field.name === fieldName);
    }

    getFieldValues(fieldName) {
        return this.getField(fieldName)?.values || [];
    }

    getFieldValue(fieldName, index = 0) {
        return this.getFieldValues(fieldName)?.[index];
    }

    isValueEmpty(values) {
        return values.length === 0 || values.every((v) => v === '' || v === null || v === undefined);
    }

    get variant() {
        return this.getFieldValue('variant');
    }

    get fragmentName() {
        return this.path.split('/').pop();
    }

    get statusVariant() {
        return this.status?.toLowerCase();
    }

    getTagTitle(id) {
        const tags = this.tags.filter((tag) => tag.id.includes(id));
        return tags[0]?.title;
    }

    get locale() {
        const match = this.path.match(PATH_TOKENS);
        return match?.groups?.parsedLocale || '';
    }

    /**
     * Updates the fragment entirely while preserving the initial value & hasChange status if not specified
     * @param {object} fragmentData
     * @param {Boolean | undefined} hasChanges
     */
    replaceFrom(fragmentData, hasChanges) {
        const clonedData = structuredClone(fragmentData);
        Object.assign(this, clonedData);
        if (hasChanges === undefined) return;
        this.hasChanges = hasChanges;
    }

    refreshFrom(fragmentData) {
        this.replaceFrom(fragmentData, false);
        this.initialValue = structuredClone(fragmentData);
        this.newTags = undefined;
    }

    discardChanges() {
        if (!this.hasChanges) return;
        this.newTags = undefined;
        this.replaceFrom(this.initialValue, false);
    }

    updateFieldInternal(fieldName, value) {
        this[fieldName] = value ?? '';
        this.hasChanges = true;
    }

    getVariations() {
        return this.getFieldValues('variations') || [];
    }

    hasVariations() {
        const variations = this.getVariations();
        return variations.length > 0;
    }

    /**
     * Updates a field's values.
     * For variations: if values match parent exactly, resets to inherited state.
     * @param {string} fieldName - The field name to update
     * @param {Array} value - The new values
     * @param {Fragment|null} [parentFragment] - The parent fragment (for variations)
     * @returns {boolean|'reset'} - true if updated, false if no change, 'reset' if reset to parent
     */
    updateField(fieldName, value, parentFragment = null) {
        const encodedValues = value.map((v) => (typeof v === 'string' ? v.normalize('NFC') : v));
        const existingField = this.getField(fieldName);
        const isTags = fieldName === 'tags';
        const parentField = parentFragment?.getField(fieldName);

        // [''] is the explicit clear sentinel for multi-value fields
        const isSingleEmptyString = encodedValues.length === 1 && encodedValues[0] === '';

        // Determine if this is a multi-value field based on the .multiple property
        const isMultiple = parentField?.multiple === true || existingField?.multiple === true;

        // For variations: if values match parent exactly, reset to inherited state
        if (parentFragment) {
            const parentValues = parentField?.values || [];
            const valuesMatchParent =
                encodedValues.length === parentValues.length && encodedValues.every((v, i) => v === parentValues[i]);

            if (valuesMatchParent) {
                // Reset field if it exists, or just confirm it should stay inherited
                this.resetFieldToParent(fieldName);
                return 'reset';
            }
        }

        if (existingField) {
            const { values } = existingField;
            // Skip [] to [''] on single-value fields (RTE initialization sends [''] for empty fields).
            // For multiple:true fields, [''] is an explicit "clear" sentinel.
            if (values.length === 0 && isSingleEmptyString && !isMultiple) {
                return false;
            }
            // No change if values are identical
            if (values.length === encodedValues.length && values.every((v, i) => v === encodedValues[i])) {
                if (isTags) this.newTags = value;
                return false;
            }
            existingField.values = encodedValues;
            // Inherit multiple from parent field if not already set
            if (parentField?.multiple && !existingField.multiple) {
                existingField.multiple = true;
            }
        } else {
            // Only create new field if there's meaningful content
            // Exception: [''] is allowed as explicit clear sentinel for multi-value fields
            const hasContent = encodedValues.length && encodedValues.some((v) => v?.trim?.());
            if (!hasContent && !(isSingleEmptyString && isMultiple)) {
                if (isTags) this.newTags = value;
                return false;
            }
            const newField = { name: fieldName, type: 'text', values: encodedValues };
            // Inherit multiple from parent field
            if (parentField?.multiple) newField.multiple = true;
            this.fields.push(newField);
        }

        this.hasChanges = true;
        if (isTags) this.newTags = value;
        return true;
    }

    getEffectiveFieldValue(fieldName, parentFragment, isVariation, index = 0) {
        const ownValue = this.getFieldValue(fieldName, index);
        if (ownValue !== undefined && ownValue !== null && ownValue !== '') {
            return ownValue;
        }
        if (!parentFragment || !isVariation) {
            return ownValue;
        }
        return parentFragment.getFieldValue(fieldName, index);
    }

    getEffectiveFieldValues(fieldName, parentFragment, isVariation) {
        const ownField = this.getField(fieldName);
        const ownValues = ownField?.values || [];

        // [] (empty array) = inherit from parent if variation
        if (ownValues.length === 0) {
            if (!parentFragment || !isVariation) {
                return [];
            }
            const parentField = parentFragment.getField(fieldName);
            return parentField?.values || [];
        }

        // For [""] (single empty string):
        // - For multi-value fields (multiple: true): explicit clear sentinel → return empty array
        // - For single-value fields (multiple: false): AEM initializes empty fields this way → inherit from parent
        const isSingleEmptyString = ownValues.length === 1 && ownValues[0] === '';
        if (isSingleEmptyString) {
            const isMultipleField = ownField?.multiple === true;
            if (isMultipleField) {
                // Explicit clear for multi-value fields
                return [];
            }
            // Single-value field with [""] - inherit from parent if variation
            if (!parentFragment || !isVariation) {
                return [];
            }
            const parentField = parentFragment.getField(fieldName);
            return parentField?.values || [];
        }

        // Has actual values - return them
        return ownValues;
    }

    getFieldState(fieldName, parentFragment, isVariation) {
        if (!isVariation || !parentFragment) {
            return 'no-parent';
        }
        const ownField = this.getField(fieldName);
        const ownValues = ownField?.values || [];
        const parentValues = parentFragment.getFieldValues(fieldName) || [];

        // [] (empty array) = inherited
        if (ownValues.length === 0) {
            return 'inherited';
        }

        // For [""] (single empty string):
        // - For multi-value fields (multiple: true): this is explicit clear sentinel → overridden
        // - For single-value fields (multiple: false): AEM initializes empty fields this way → inherited
        const isSingleEmptyString = ownValues.length === 1 && ownValues[0] === '';
        if (isSingleEmptyString) {
            const isMultipleField = ownField?.multiple === true;
            if (!isMultipleField) {
                return 'inherited';
            }
            // For multiple fields, [""] is explicit clear - fall through to comparison
        }

        // Has actual values - compare with parent
        const normalizeForComparison = (v) => {
            if (v === null || v === undefined) return '';
            if (typeof v === 'string') {
                return v
                    .normalize('NFC')
                    .trim()
                    .replace(/\s+role="[^"]*"/g, '')
                    .replace(/\s+aria-level="[^"]*"/g, '');
            }
            return String(v);
        };

        const areEqual =
            ownValues.length === parentValues.length &&
            ownValues.every((v, i) => normalizeForComparison(v) === normalizeForComparison(parentValues[i]));

        return areEqual ? 'same-as-parent' : 'overridden';
    }

    isFieldOverridden(fieldName, parentFragment, isVariation) {
        return this.getFieldState(fieldName, parentFragment, isVariation) === 'overridden';
    }

    /**
     * Prepares a variation fragment for saving by resetting fields that match parent values.
     * This ensures we don't save inherited values as explicit overrides.
     * @param {Fragment} parentFragment - The parent fragment to compare against
     * @returns {Fragment} A clone of this fragment with inherited fields reset to []
     */
    prepareVariationForSave(parentFragment) {
        if (!parentFragment) return this;

        // Create a new Fragment instance from this fragment's data (constructor handles cloning)
        const prepared = new Fragment(this);

        // Fields that should never be reset (they're fragment-specific, not inherited)
        const excludeFields = ['variations', 'tags', 'originalId', 'locReady'];

        for (const field of prepared.fields) {
            if (excludeFields.includes(field.name)) continue;

            const fieldState = this.getFieldState(field.name, parentFragment, true);

            // If field is inherited or same-as-parent, reset to empty array
            // Only keep values that are truly overridden (different from parent)
            if (fieldState === 'inherited' || fieldState === 'same-as-parent') {
                field.values = [];
            }
        }

        return prepared;
    }

    resetFieldToParent(fieldName) {
        const fieldIndex = this.fields.findIndex((field) => field.name === fieldName);
        if (fieldIndex !== -1) {
            this.fields.splice(fieldIndex, 1);
            this.hasChanges = true;
            return true;
        }
        return false;
    }

    /**
     * Checks whether a path is a grouped (pzn) variation path.
     * @param {string} path
     * @returns {boolean}
     */
    static isGroupedVariationPath(path) {
        return path?.includes(`/${PZN_FOLDER}/`) ?? false;
    }

    /**
     * Categorizes all variation references in a single pass into locale, promo, and grouped buckets.
     * Each variation is classified into exactly one category (grouped > promo > locale).
     * @returns {{ locale: Object[], promo: Object[], grouped: Object[] }}
     */
    #categorizeVariations() {
        const variationPaths = this.getVariations();
        if (!variationPaths.length || !this.references?.length) {
            return { locale: [], promo: [], grouped: [] };
        }

        const referencesByPath = new Map(this.references.map((ref) => [ref.path, ref]));

        const currentMatch = this.path.match(PATH_TOKENS);
        const { surface, parsedLocale: currentLocale, fragmentPath } = currentMatch?.groups || {};

        const locale = [];
        const promo = [];
        const grouped = [];

        for (const path of variationPaths) {
            const reference = referencesByPath.get(path);
            if (!reference) continue;

            if (Fragment.isGroupedVariationPath(path)) {
                grouped.push(reference);
                continue;
            }

            const isPromo = reference.tags?.some((t) => t.id?.startsWith(TAG_PROMOTION_PREFIX));
            if (isPromo) {
                promo.push(reference);
                continue;
            }

            if (surface && currentLocale && fragmentPath) {
                const refMatch = path.match(PATH_TOKENS);
                if (refMatch?.groups) {
                    const r = refMatch.groups;
                    if (r.surface === surface && r.fragmentPath === fragmentPath && r.parsedLocale !== currentLocale) {
                        locale.push(reference);
                    }
                }
            }
        }

        return { locale, promo, grouped };
    }

    /**
     * Lists all locale variations of the fragment (regional variations).
     * @returns {Object[]}
     */
    listLocaleVariations() {
        return this.#categorizeVariations().locale;
    }

    /**
     * Lists all grouped (pzn) variations of the fragment.
     * @returns {Object[]}
     */
    listGroupedVariations() {
        return this.#categorizeVariations().grouped;
    }

    /**
     * Gets the count of grouped (pzn) variations.
     * @returns {number}
     */
    getGroupedVariationCount() {
        return this.#categorizeVariations().grouped.length;
    }

    /**
     * Gets the count of locale variations.
     * @returns {number}
     */
    getLocaleVariationCount() {
        return this.#categorizeVariations().locale.length;
    }

    /**
     * Gets the count of promo variations.
     * @returns {number}
     */
    getPromoVariationCount() {
        return this.#categorizeVariations().promo.length;
    }

    /**
     * Gets the total count of all variations (locale + promo + grouped).
     * @returns {number}
     */
    getTotalVariationCount() {
        const { locale, promo, grouped } = this.#categorizeVariations();
        return locale.length + promo.length + grouped.length;
    }
}

import { LitElement, html, css } from 'lit';
import ReactiveController from './reactivity/reactive-controller.js';
import { extractLocaleFromPath, generateCodeToUse, getService, showToast } from './utils.js';
import { getFragmentPartsToUse, MODEL_WEB_COMPONENT_MAPPING } from './editor-panel.js';
import Store from './store.js';
import { closePreview, openPreview } from './mas-card-preview.js';
import { CARD_MODEL_PATH } from './constants.js';
import { MasRepository } from './mas-repository.js';
import router from './router.js';
import './mas-variation-dialog.js';

class MasFragmentTable extends LitElement {
    static properties = {
        fragmentStore: { type: Object, attribute: false },
        offerData: { type: Object, state: true, attribute: false },
        expanded: { type: Boolean, attribute: false },
        nested: { type: Boolean, attribute: false },
        canCreateVariation: { type: Boolean, attribute: false },
        toggleExpand: { type: Function, attribute: false },
        showVariationDialog: { state: true },
        failedPrice: { type: Boolean, state: true },
    };

    static styles = css`
        .price-error-title {
            color: var(--merch-color-error, #d73220);
            font-weight: 600;
        }
    `;

    constructor() {
        super();
        this.offerData = null;
        this.expanded = false;
        this.nested = false;
        this.canCreateVariation = true;
        this.showVariationDialog = false;
        this.failedPrice = false;
    }

    #reactiveControllers = new ReactiveController(this);

    /** @type {MasRepository} */
    get repository() {
        return document.querySelector('mas-repository');
    }

    createRenderRoot() {
        return this;
    }

    connectedCallback() {
        super.connectedCallback();
        this.loadOfferData();
    }

    getFragmentName(data) {
        const webComponentName = MODEL_WEB_COMPONENT_MAPPING[data?.model?.path];
        const fragmentParts = getFragmentPartsToUse(Store, data).fragmentParts;
        return `${webComponentName}: ${fragmentParts}`;
    }

    get data() {
        return this.fragmentStore.value;
    }

    async loadOfferData() {
        this.failedPrice = false;
        const wcsOsi = this.data.getFieldValue('osi');
        if (!wcsOsi) return;
        try {
            const service = getService();
            const priceOptions = service.collectPriceOptions({ wcsOsi });
            const [offersPromise] = service.resolveOfferSelectors(priceOptions);
            if (!offersPromise) {
                this.failedPrice = true;
                return;
            }
            const [offer] = await offersPromise;
            if (!offer) {
                this.failedPrice = true;
                return;
            }
            this.offerData = offer;
        } catch (error) {
            this.failedPrice = true;
        }
    }

    update(changedProperties) {
        if (changedProperties.has('fragmentStore')) {
            this.#reactiveControllers.updateStores([this.fragmentStore]);
        }
        super.update(changedProperties);
    }

    get icon() {
        const iconSrc = this.data.getFieldValue('mnemonicIcon'); // Returns only the first one
        if (!iconSrc) return '';
        return html`<img class="mnemonic-icon" src=${this.data.getFieldValue('mnemonicIcon')} />`;
    }

    get name() {
        return generateCodeToUse(this.data, Store.search.get().path, Store.page.get()).authorPath;
    }

    get price() {
        const osi = this.data.getFieldValue('osi');
        if (!osi) return '';
        if (this.failedPrice) {
            return html`<span class="price-error-title">Price Unavailable</span>`;
        }
        return html`<span is="inline-price" data-template="price" data-wcs-osi=${osi}></span>`;
    }

    openCardPreview() {
        openPreview(this.fragmentStore.value.id, { left: 'min(300px, 15%)' });
    }

    handleActionsClick(event) {
        event.stopPropagation();
        const actionMenu = event.currentTarget.querySelector('sp-action-menu');
        if (actionMenu) {
            actionMenu.open = !actionMenu.open;
        }
    }

    handleCreateVariation(event) {
        event.stopPropagation();
        this.showVariationDialog = true;
    }

    handleVariationDialogCancel() {
        this.showVariationDialog = false;
    }

    handleFragmentCopied(event) {
        this.showVariationDialog = false;
        const { fragment } = event.detail;
        if (fragment?.id) {
            const locale = extractLocaleFromPath(fragment.path);
            router.navigateToFragmentEditor(fragment.id, { locale });
        }
    }

    handleEditFragment(event) {
        event.stopPropagation();
        const fragment = this.fragmentStore.value;
        if (fragment?.id) {
            const locale = extractLocaleFromPath(fragment.path);
            router.navigateToFragmentEditor(fragment.id, { locale });
        }
    }

    getTruncatedOfferId() {
        const offerId = this.offerData?.offerId;
        if (!offerId || offerId.length <= 5) return offerId;
        return `...${offerId.slice(-5)}`;
    }

    async copyOfferIdToClipboard(e) {
        e.stopPropagation();
        const offerId = this.offerData?.offerId;
        if (!offerId) return;

        try {
            await navigator.clipboard.writeText(offerId);
            showToast('Offer ID copied to clipboard', 'positive');
        } catch (err) {
            console.error('Failed to copy offer ID:', err);
            showToast('Failed to copy Offer ID', 'negative');
        }
    }

    render() {
        const data = this.fragmentStore.value;
        return html`
            ${this.showVariationDialog
                ? html`<mas-variation-dialog
                      .fragment=${data}
                      .isVariation=${false}
                      .offerData=${this.offerData}
                      @cancel=${this.handleVariationDialogCancel}
                      @fragment-copied=${this.handleFragmentCopied}
                  ></mas-variation-dialog>`
                : ''}
            <sp-table-row
                value="${data.id}"
                class="${this.expanded ? 'expanded' : ''} ${this.failedPrice ? 'price-failed' : ''}"
            >
                ${this.nested
                    ? ''
                    : html`<sp-table-cell class="expand-cell" @click=${this.toggleExpand}>
                          <button class="expand-button" aria-label="${this.expanded ? 'Collapse' : 'Expand'} row">
                              ${this.expanded
                                  ? html`<sp-icon-chevron-down></sp-icon-chevron-down>`
                                  : html`<sp-icon-chevron-right></sp-icon-chevron-right>`}
                          </button>
                      </sp-table-cell>`}
                <sp-table-cell class="name">
                    ${this.nested
                        ? html`${data.locale}`
                        : html`<div class="icon">${this.icon}</div>
                              ${this.getFragmentName(data)}`}
                </sp-table-cell>
                <sp-table-cell class="title">${data.title}</sp-table-cell>
                <sp-table-cell class="offer-id">
                    <span class="offer-id-text" title=${this.offerData?.offerId}> ${this.getTruncatedOfferId()} </span>
                    ${this.offerData?.offerId
                        ? html`<button
                              class="copy-icon-button"
                              aria-label="Copy Offer ID to clipboard"
                              @click=${this.copyOfferIdToClipboard}
                          >
                              <sp-icon-copy class="copy-icon"></sp-icon-copy>
                          </button>`
                        : ''}
                </sp-table-cell>
                <sp-table-cell class="offer-type">${this.offerData?.offerType}</sp-table-cell>
                <sp-table-cell class="last-modified-by">${data.modified?.by}</sp-table-cell>
                <sp-table-cell class="price">${this.price}</sp-table-cell>
                <sp-table-cell class="status ${data.status?.toLowerCase()}-cell"
                    ><div class="status-dot"></div>
                    <span class="status-text">${data.status}</span></sp-table-cell
                >
                <sp-table-cell class="actions">
                    ${this.failedPrice
                        ? html`<sp-icon-alert class="price-error-icon"></sp-icon-alert>`
                        : html`<sp-action-menu placement="bottom-end" quiet>
                              <sp-icon-more slot="icon"></sp-icon-more>
                              <sp-menu-item
                                  @click=${this.handleCreateVariation}
                                  ?hidden=${this.nested || !this.canCreateVariation}
                              >
                                  <sp-icon-user-group slot="icon"></sp-icon-user-group>
                                  Create variation
                              </sp-menu-item>
                              <sp-menu-item @click=${this.handleEditFragment}>
                                  <sp-icon-edit slot="icon"></sp-icon-edit>
                                  Edit fragment
                              </sp-menu-item>
                          </sp-action-menu>`}
                </sp-table-cell>
                ${data.model?.path === CARD_MODEL_PATH
                    ? html`<sp-table-cell class="preview" @mouseover=${this.openCardPreview} @mouseout=${closePreview}
                          ><sp-icon-preview label="Preview item"></sp-icon-preview
                      ></sp-table-cell>`
                    : html`<sp-table-cell class="preview"></sp-table-cell>`}
            </sp-table-row>
        `;
    }
}

